-- Weekly Arena 2026-W49: generated by scripts/weekly-arena.ts. Safe to rerun (skips if the title already exists).
insert into public.arenas(title, description, starts_at, ends_at, duration_minutes, status, questions)
select 'Weekly Arena 2026-W49', 'Fresh weekly set of 10 numeric questions across Algebra, Geometry, Combinatorics and Number Theory. Each question allows three submissions. New questions every week, none repeated from earlier arenas.', '2026-11-30T00:00:00.000Z', '2026-12-07T00:00:00.000Z', 60, 'published', $WK0b977942ede5$[{"id":"wk-2026-w49-01-82b8","title":"Reciprocal Powers","topic":"Algebra","level":"Intermediate","question":"A positive real number $x$ satisfies $x + \\dfrac{1}{x} = 4$. Find $x^{4} + \\dfrac{1}{x^{4}}$.","type":"text","correctAnswer":"194","hint":"Set $T_m=x^m+x^{-m}$; then $T_m=4T_{m-1}-T_{m-2}$.","solution":"With $T_0=2$, $T_1=4$ the recurrence gives $T_{4}=194$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":3,"abstraction":2,"points":47,"difficulty":-0.52},{"id":"wk-2026-w49-02-a11b","title":"Triangles From Diagonals Only","topic":"Geometry","level":"Intermediate","question":"Three vertices of a convex $13$-gon are chosen so that none of the three sides of the resulting triangle is a side of the polygon. How many such triangles are there?","type":"text","correctAnswer":"156","hint":"Count all triangles and remove those that use at least one polygon side, by inclusion-exclusion.","solution":"The count is $\\dfrac{n(n-4)(n-5)}{6}$ with $n=13$, i.e. $156$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w49-03-aa76","title":"No Neighbouring Ones","topic":"Combinatorics","level":"Intermediate","question":"How many binary strings of length $21$ contain no two consecutive $1$s?","type":"text","correctAnswer":"28657","hint":"Condition on the last digit to get a Fibonacci-type recurrence.","solution":"Let $f(n)=f(n-1)+f(n-2)$ with $f(1)=2$, $f(2)=3$; then $f(21)=28657$.","answerMode":"numeric-grid","answerDigits":5,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w49-04-2d9b","title":"Tangent and Secant","topic":"Geometry","level":"Intermediate","question":"From an external point $P$, a tangent $PT$ of length $33$ and a secant meeting the circle at $A$ and $B$ are drawn, with $PA < PB$ and $PA=9$. Find $PA + PB + PT$.","type":"text","correctAnswer":"163","hint":"Apply the power of a point: $PT^2=PA\\cdot PB$.","solution":"$PB=33^2/9=121$, so the sum is $9+121+33=163$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":3,"abstraction":3,"points":53,"difficulty":-0.28},{"id":"wk-2026-w49-05-8039","title":"A Blocked Lattice Path","topic":"Combinatorics","level":"Intermediate","question":"A path from $(0,0)$ to $(6,5)$ moves only one unit right or one unit up at each step. How many such paths avoid the point $(3,4)$?","type":"text","correctAnswer":"322","hint":"Subtract the paths that pass through the forbidden point from the total.","solution":"$\\binom{11}{6}-\\binom{7}{3}\\binom{4}{3}=322$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w49-06-a5e9","title":"Three Remainders","topic":"Number Theory","level":"Intermediate","question":"Find the smallest positive integer $n$ such that $n\\equiv 4 \\pmod{5}$, $n\\equiv 5 \\pmod{9}$, $n\\equiv 8 \\pmod{11}$.","type":"text","correctAnswer":"239","hint":"The moduli are pairwise coprime, so the Chinese Remainder Theorem gives a unique residue class.","solution":"Combining the congruences gives the residue class of $239$ modulo $495$, and $239$ is its smallest positive member.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w49-07-ebe8","title":"The Last Three Digits","topic":"Number Theory","level":"Advanced","question":"Find the remainder when $13^{313}$ is divided by $1000$.","type":"text","correctAnswer":"253","hint":"Work modulo $8$ and modulo $125$ separately and combine, or use the order of the unit in $(\\mathbb Z/1000)^\\times$.","solution":"Modular exponentiation gives $13^{313}\\equiv 253 \\pmod{1000}$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w49-08-bfd0","title":"Powers of the Roots","topic":"Algebra","level":"Advanced","question":"Let $r$ and $s$ be the roots of $t^2 - 9t + 4 = 0$. Find the remainder when $r^{8} + s^{8}$ is divided by $1000$.","type":"text","correctAnswer":"697","hint":"Let $S_k=r^k+s^k$. Then $S_k=9S_{k-1}-4S_{k-2}$, with $S_0=2$, $S_1=9$.","solution":"Using $S_k=9S_{k-1}-4S_{k-2}$ from $S_0=2$, $S_1=9$ gives $S_{8}=28057697$, whose remainder modulo $1000$ is $697$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w49-09-8c3e","title":"A Floor Sum","topic":"Algebra","level":"Advanced","question":"Compute $\\displaystyle\\sum_{k=1}^{30} \\left\\lfloor \\frac{8k}{11} \\right\\rfloor$.","type":"text","correctAnswer":"324","hint":"Write $8k=11q+r$ and track how the remainder cycles with period $11$.","solution":"Evaluating each floor term and adding gives $324$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w49-10-4895","title":"Lattice Points Inside","topic":"Geometry","level":"Advanced","question":"A triangle has vertices $(0,0)$, $(7,3)$ and $(4,6)$ in the coordinate plane. How many points with integer coordinates lie strictly inside the triangle?","type":"text","correctAnswer":"13","hint":"Use Pick's theorem: $A=I+B/2-1$, with $B$ counted by gcds along each side.","solution":"Twice the area is $30$ and the boundary has $B=6$ lattice points, so $I=(30-6+2)/2=13$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0}]$WK0b977942ede5$::jsonb
